159	CREATE OR REPLACE FUNCTION public.ensure_default_family()
160	 RETURNS uuid
161	 LANGUAGE plpgsql
162	 SECURITY DEFINER
163	 SET search_path TO 'public'
164	AS $function$
165	declare
166	  uid uuid := auth.uid();
167	  fam_id uuid;
168	begin
169	  if uid is null then
170	    raise exception 'ensure_default_family() requires auth.uid()';
171	  end if;
172	
173	  -- Try to find an active default family
174	  select fm.family_id into fam_id
175	  from public.family_members fm
176	  where fm.user_id = uid and fm.status = 'active' and fm.is_default = true
177	  limit 1;
178	
179	  if fam_id is not null then
180	    return fam_id;
181	  end if;
182	
183	  -- If no default, try any active membership
184	  select fm.family_id into fam_id
185	  from public.family_members fm
186	  where fm.user_id = uid and fm.status = 'active'
187	  limit 1;
188	
189	  if fam_id is not null then
190	    return fam_id;
191	  end if;
192	
193	  -- Create a new family owned by this user and mark membership as default
194	  insert into public.families (name, created_by) values (null, uid) returning id into fam_id;
195	  insert into public.family_members (family_id, user_id, role, status, is_default)
196	  values (fam_id, uid, 'owner', 'active', true)
197	  on conflict do nothing;
198	
199	  return fam_id;
200	end;
201	$function$
