204	CREATE OR REPLACE FUNCTION public.find_user_by_email(email_address text)
205	 RETURNS uuid
206	 LANGUAGE plpgsql
207	 SECURITY DEFINER
208	 SET search_path TO 'public'
209	AS $function$
210	declare
211	  user_uuid uuid;
212	begin
213	  -- First check auth.users primary email
214	  select id into user_uuid
215	  from auth.users
216	  where lower(email) = lower(email_address)
217	  limit 1;
218	
219	  if user_uuid is not null then
220	    return user_uuid;
221	  end if;
222	
223	  -- Check profile emails
224	  select user_id into user_uuid
225	  from public.profiles
226	  where lower(email_1) = lower(email_address)
227	     or lower(email_2) = lower(email_address)
228	     or lower(email_3) = lower(email_address)
229	     or lower(email_4) = lower(email_address)
230	     or lower(email_5) = lower(email_address)
231	  limit 1;
232	
233	  return user_uuid;
234	end;
