238	CREATE OR REPLACE FUNCTION public.insert_receipt_with_context(receipt_data jsonb)
239	 RETURNS jsonb
240	 LANGUAGE plpgsql
241	 SECURITY DEFINER
242	AS $function$
243	DECLARE
244	  inserted_receipt jsonb;
245	  user_id_val uuid;
246	BEGIN
247	  -- Extract user_id from the receipt_data
248	  user_id_val := (receipt_data->>'user_id')::uuid;
249	
250	  -- Set the local auth.uid() for this transaction
251	  -- This allows triggers that depend on auth.uid() to work
252	  PERFORM set_config('request.jwt.claims', json_build_object('sub', user_id_val)::text, true);
253	
254	  -- Insert the receipt
255	  INSERT INTO receipts (
256	    user_id,
257	    receipt_image_path,
258	    merchant_name,
259	    total_amount,
260	    tax,
261	    transaction_date,
262	    currency,
263	    credit_card_name,
264	    credit_card_last_4
265	  )
266	  VALUES (
267	    user_id_val,
268	    receipt_data->>'receipt_image_path',
269	    receipt_data->>'merchant_name',
270	    (receipt_data->>'total_amount')::numeric,
271	    (receipt_data->>'tax')::numeric,
272	    (receipt_data->>'transaction_date')::date,
273	    receipt_data->>'currency',
274	    receipt_data->>'credit_card_name',
275	    receipt_data->>'credit_card_last_4'
276	  )
277	  RETURNING to_jsonb(receipts.*) INTO inserted_receipt;
278	
279	  RETURN inserted_receipt;
280	END;
281	$function$
